def column_cells(col):
    """(row, value) of the nonzero cells in a column, top to bottom."""
    return [(r, v) for r, v in enumerate(col) if v != 0]

def extend_up(col, cells, limit):
    """Paint each cell's color upward over zeros until a different color or row 0; changes stay above limit."""
    res = col[:]
    for r, v in cells:
        for rr in range(r - 1, max(limit - 1, -1), -1):
