                res[rr] = v
            else:
                break
    return res

def marker_column_fill(grid, marker=5):
    """In each column marked by marker in the last row: the lowest other color fills a middle band, marker fills below it, top colors extend upward."""
    g = [r[:] for r in grid]; h = len(g)
